import{_ as e,o as i,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Detect, Decide, Fence- Resolving Netsplits in 3-AZ Stretch Cluster - Kamoltat (Junior) Sirivadhna","description":"","frontmatter":{"title":"Detect, Decide, Fence- Resolving Netsplits in 3-AZ Stretch Cluster - Kamoltat (Junior) Sirivadhna","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","distributed storage","network split","3AZ stretch cluster","high availability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Detect_Decide_Fence_-_Resolving_Netsplits_in_3-AZ_Stretch_Cluster_-_Kamoltat_Junior_Sirivadhna.md","filePath":"posts/2025/Detect_Decide_Fence_-_Resolving_Netsplits_in_3-AZ_Stretch_Cluster_-_Kamoltat_Junior_Sirivadhna.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Detect_Decide_Fence_-_Resolving_Netsplits_in_3-AZ_Stretch_Cluster_-_Kamoltat_Junior_Sirivadhna.md"};function a(n,t,s,c,_,h){return i(),r("div",null,[...t[0]||(t[0]=[l('<h3 id="ceph-3az-stretch-cluster-网络分裂解决方案会议纪要" tabindex="-1">Ceph 3AZ Stretch Cluster 网络分裂解决方案会议纪要 <a class="header-anchor" href="#ceph-3az-stretch-cluster-网络分裂解决方案会议纪要" aria-label="Permalink to &quot;Ceph 3AZ Stretch Cluster 网络分裂解决方案会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><ul><li><strong>主讲人</strong>: Kamotad（Junior），Ceph贡献者，专注于分布式存储领域</li><li><strong>主题</strong>: 3AZ Stretch Cluster中的网络分裂问题及解决方案</li><li><strong>核心问题</strong>: 在3AZ（三数据中心）架构中，如何检测和解决网络分裂，避免split-brain现象，确保集群高可用性。</li></ul><h4 id="关键讨论点" tabindex="-1">关键讨论点 <a class="header-anchor" href="#关键讨论点" aria-label="Permalink to &quot;关键讨论点&quot;">​</a></h4><h4 id="_1-问题背景" tabindex="-1">1. <strong>问题背景</strong> <a class="header-anchor" href="#_1-问题背景" aria-label="Permalink to &quot;1. **问题背景**&quot;">​</a></h4><ul><li><strong>3AZ架构</strong>: 数据分布在三个DC，每个DC包含两份数据副本，允许单个DC完全故障。</li><li><strong>网络分裂场景</strong>: DC1与DC2断开连接，但均与DC3保持连通。此时，OSDs因心跳失败报告对方为<code>down</code>，导致PGs频繁切换状态，IO暂停。</li><li><strong>挑战</strong>: 需快速隔离一个DC，确保剩余DC继续服务。</li></ul><h4 id="_2-解决方案设计" tabindex="-1">2. <strong>解决方案设计</strong> <a class="header-anchor" href="#_2-解决方案设计" aria-label="Permalink to &quot;2. **解决方案设计**&quot;">​</a></h4><ul><li><strong>网络分裂检测</strong>: 利用monitor间的<strong>connection scores</strong>构建连接图，识别断开的数据中心，并在<code>ceph status</code>中显示健康警告。</li><li><strong>选择幸存DC的算法</strong>（BK算法）: 找到最大连通子图，确保最多DC参与服务。通过启发式规则选择最优clique，优先级包括OSD总权重、存活monitor数量、monitor连接分数等。</li><li><strong>隔离（Fencing）执行</strong>: <ul><li><strong>预检查</strong>: 模拟排除被隔离DC后的PG acting set，确保不违反<code>min_size</code>。</li><li><strong>全局标记</strong>: 设置<code>no_recover</code>和<code>no_backfill</code>，避免数据迁移干扰。</li><li><strong>隔离生效</strong>: Monitor忽略被隔离DC的OSD故障报告，PG acting set排除其OSD。</li></ul></li></ul><h4 id="_3-隔离恢复与边界场景" tabindex="-1">3. <strong>隔离恢复与边界场景</strong> <a class="header-anchor" href="#_3-隔离恢复与边界场景" aria-label="Permalink to &quot;3. **隔离恢复与边界场景**&quot;">​</a></h4><ul><li><strong>恢复条件</strong>: 网络分裂消失且持续超过<code>lift_fencing_threshold</code>。</li><li><strong>动态调整</strong>: 若网络状态变化导致更优clique出现，需超过<code>switch_fence_threshold</code>才切换隔离目标。</li></ul><h4 id="_4-扩展性与优化建议" tabindex="-1">4. <strong>扩展性与优化建议</strong> <a class="header-anchor" href="#_4-扩展性与优化建议" aria-label="Permalink to &quot;4. **扩展性与优化建议**&quot;">​</a></h4><ul><li><strong>多DC支持</strong>: 当前算法支持3-5个DC，未来可扩展。</li><li><strong>链路感知</strong>: 考虑数据中心间延迟，优化clique选择。</li><li><strong>用户自定义</strong>: 允许管理员配置DC优先级或权重。</li><li><strong>RGW集成</strong>: 需在RGW中暴露隔离状态，确保客户端请求路由到幸存DC。</li></ul><h4 id="_5-行动计划" tabindex="-1">5. <strong>行动计划</strong> <a class="header-anchor" href="#_5-行动计划" aria-label="Permalink to &quot;5. **行动计划**&quot;">​</a></h4><ul><li><strong>代码落地</strong>: 将解决方案集成至Ceph主线，完善<code>switch_fence_threshold</code>逻辑。</li><li><strong>测试验证</strong>: 模拟多DC网络分裂场景，验证算法效率与稳定性。</li><li><strong>用户侧增强</strong>: 提供配置选项，完善文档说明。</li></ul><h4 id="遗留问题" tabindex="-1">遗留问题 <a class="header-anchor" href="#遗留问题" aria-label="Permalink to &quot;遗留问题&quot;">​</a></h4><ul><li><strong>RGW集成</strong>: 需明确如何在高层级服务中传递隔离状态。</li><li><strong>动态权重</strong>: 是否引入链路质量指标优化clique选择？</li></ul><h4 id="专业术语保留-中英对照" tabindex="-1">专业术语保留（中英对照） <a class="header-anchor" href="#专业术语保留-中英对照" aria-label="Permalink to &quot;专业术语保留（中英对照）&quot;">​</a></h4><ul><li>Split-brain（脑裂）</li><li>CRUSH algorithm</li><li>OSD/MON/MDS/PG</li><li>RADOS/librados</li><li>Erasure coding（纠删码）</li><li>Acting set</li><li>Clique（最大连通子图）</li><li>Fencing（隔离）</li><li>Stretch cluster</li></ul>',18)])])}const u=e(o,[["render",a]]);export{g as __pageData,u as default};
